/// `nir_alu_type` (nir_defines.h): a base type ORed with a bit size.
pub mod alu_type {
    pub const INVALID: u8 = 0;
    pub const INT: u8 = 2;
    pub const UINT: u8 = 4;
    pub const BOOL: u8 = 6;
    pub const FLOAT: u8 = 128;
    /// The bit size of a sized type (0 for an unsized one).
    pub const SIZE_MASK: u8 = 121;
    pub const BASE_TYPE_MASK: u8 = 134;
}

/// `NIR_OP_IS_*` (nir.h), the bits of `NirOpInfo::algebraic_properties`.
pub mod op_is {
    pub const _2SRC_COMMUTATIVE: u8 = 1;
    pub const ASSOCIATIVE: u8 = 2;
    pub const SELECTION: u8 = 4;
    pub const INEXACT_ASSOCIATIVE: u8 = 8;
}

/// `nir_fp_*` (nir.h), the bits of an ALU instruction's `fp_math_ctrl`.
pub mod fp {
    pub const PRESERVE_SIGNED_ZERO: u8 = 1;
    pub const PRESERVE_INF: u8 = 2;
    pub const PRESERVE_NAN: u8 = 4;
    pub const NO_CONTRACT: u8 = 8;
    pub const NO_REASSOC: u8 = 16;
    pub const NO_TRANSFORM: u8 = 32;
    pub const EXACT: u8 = 56;
    pub const PRESERVE_SZ_INF_NAN: u8 = 7;
    pub const FAST_MATH: u8 = 0;
    pub const NO_FAST_MATH: u8 = 63;
}

/// `nir_op_info` (nir.h), as nir_opcodes_c.py fills it.
#[derive(Debug)]
pub struct NirOpInfo {
    pub name: &'static str,
    pub num_inputs: u8,
    /// 0: per component; else the fixed component count of the output.
    pub output_size: u8,
    pub output_type: u8,
    pub input_sizes: &'static [u8],
    pub input_types: &'static [u8],
    pub is_conversion: bool,
    /// `op_is` bits.
    pub algebraic_properties: u8,
    /// `fp` bits the opcode honours.
    pub valid_fp_math_ctrl: u8,
    /// In `REACHABLE`.
    pub reachable: bool,
}

